package ktanesolver.module.modded.regular.jackolantern;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.PortType;import ktanesolver.logic.*;class JackOLanternSolverTest{private final JackOLanternSolver solver=new JackOLanternSolver();@Test void mapsAllTwelveTableConditions(){assertMatch(bomb(Map.of("A",false),0,Set.of()),1,1);assertMatch(bomb(Map.of(),0,Set.of()),1,2);assertMatch(bomb(Map.of(),1,Set.of(PortType.DVI)),1,3);assertMatch(bomb(Map.of("CAR",false),1,Set.of()),1,4);assertMatch(bomb(Map.of(),1,Set.of(PortType.SERIAL,PortType.PARALLEL)),2,1);assertMatch(bomb(Map.of("SIG",true),1,Set.of()),2,2);assertMatch(bomb(Map.of(),1,Set.of()),2,3);assertMatch(bomb(Map.of("A",true),1,Set.of()),2,4);assertMatch(bomb(Map.of(),2,Set.of()),3,1);assertMatch(bomb(Map.of(),1,Set.of()),3,2);assertMatch(bomb(Map.of(),1,Set.of(PortType.PS2,PortType.DVI)),3,3);assertMatch(bomb(Map.of("TRN",false),1,Set.of()),3,4);}@Test void noseInvertsAndWrongFeaturesCanProduceTreat(){BombEntity b=bomb(Map.of(),1,Set.of(PortType.RJ45));assertThat(solve(b,new JackOLanternInput(3,2,false)).press()).isEqualTo("treat");assertThat(solve(b,new JackOLanternInput(3,2,true)).press()).isEqualTo("trick");}@Test void validatesPatterns(){assertThat(solver.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new JackOLanternInput(0,1,false))).isInstanceOf(SolveFailure.class);}@SuppressWarnings("unchecked")private JackOLanternOutput solve(BombEntity b,JackOLanternInput i){return((SolveSuccess<JackOLanternOutput>)solver.solve(new RoundEntity(),b,new ModuleEntity(),i)).output();}private void assertMatch(BombEntity b,int e,int m){assertThat(solve(b,new JackOLanternInput(e,m,false)).press()).isEqualTo("trick");}private static BombEntity bomb(Map<String,Boolean>indicators,int batteries,Set<PortType>ports){BombEntity b=new BombEntity();b.setIndicators(indicators);b.setAaBatteryCount(batteries);if(!ports.isEmpty())b.replacePortPlates(List.of(ports));return b;}}
